    79→    create: {
    80→      shop,
    81→      planId,
    82→      billingInterval,
    83→      shopifySubscriptionId,
    84→      status,
    85→    },
    86→    update: {
    87→      planId,
    88→      billingInterval,
    89→      shopifySubscriptionId,
    90→      status,
    91→    },
    92→  });
    93→
    94→  return {
    95→    planId,
    96→    planTier,
    97→    billingInterval,
    98→    shopifySubscriptionId,
    99→    status,
   100→    trialEndsAt: null,
